import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import type { ComponentRef, Ref } from 'react';
import { forwardRef } from 'react';
import styles from './Text.module.css';

type TextElement = 'p' | 'span' | 'small' | 'strong' | 'em' | 'div';
type TextSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type TextWeight = 'regular' | 'medium' | 'semibold' | 'bold';
type TextTone = 'default' | 'muted' | 'primary' | 'destructive';
type TextAlign = 'start' | 'center' | 'end' | 'left' | 'right' | 'justify';

type TextRootProps = HTMLArkProps<'p'> & {
  as?: TextElement;
  size?: TextSize;
  weight?: TextWeight;
  tone?: TextTone;
  align?: TextAlign;
  truncate?: boolean;
  lineClamp?: number;
};

const Text = forwardRef<HTMLElement, TextRootProps>(function Text(
  {
    as = 'p',
    size = as === 'small' ? 'sm' : 'md',
    weight = as === 'strong' ? 'semibold' : 'regular',
    tone = 'default',
    align,
    truncate,
    lineClamp,
    className,
    style,
    ...props
  },
  ref,
) {
  const Element = ark[as] as typeof ark.p;
  const clamp = Number.isInteger(lineClamp) && (lineClamp ?? 0) > 0 ? lineClamp : undefined;

  return (
    <Element
      {...props}
      ref={ref as Ref<ComponentRef<typeof ark.p>>}
      data-scope="text"
      data-part="root"
      data-slot="text-root"
      data-size={size}
      data-weight={weight}
      data-tone={tone}
      data-align={align}
      data-truncate={truncate ? '' : undefined}
      data-line-clamp={clamp === undefined ? undefined : ''}
      className={clsx(styles.root, className)}
      style={clamp === undefined ? style : { ...style, WebkitLineClamp: clamp }}
    />
  );
});

export { Text };
export type { TextAlign, TextElement, TextRootProps, TextSize, TextTone, TextWeight };

@layer moduix.components {
  .root {
    margin: 0;
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-md);
    font-weight: var(--moduix-weight-regular);
    line-height: var(--moduix-line-height-text-md);
    letter-spacing: 0;
    overflow-wrap: anywhere;

    &[data-size='xs'] {
      font-size: var(--moduix-text-xs);
      line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='sm'] {
      font-size: var(--moduix-text-sm);
      line-height: var(--moduix-line-height-text-sm);
    }

    &[data-size='lg'] {
      font-size: var(--moduix-text-lg);
      line-height: var(--moduix-line-height-text-lg);
    }

    &[data-size='xl'] {
      font-size: var(--moduix-text-xl);
      line-height: var(--moduix-line-height-text-xl);
    }

    &[data-weight='medium'] {
      font-weight: var(--moduix-weight-medium);
    }

    &[data-weight='semibold'] {
      font-weight: var(--moduix-weight-semibold);
    }

    &[data-weight='bold'] {
      font-weight: var(--moduix-weight-bold);
    }

    &[data-tone='muted'] {
      color: var(--moduix-color-muted-foreground);
    }

    &[data-tone='primary'] {
      color: var(--moduix-color-primary);
    }

    &[data-tone='destructive'] {
      color: var(--moduix-color-destructive);
    }

    &[data-align='start'] {
      text-align: start;
    }

    &[data-align='center'] {
      text-align: center;
    }

    &[data-align='end'] {
      text-align: end;
    }

    &[data-align='left'] {
      text-align: left;
    }

    &[data-align='right'] {
      text-align: right;
    }

    &[data-align='justify'] {
      text-align: justify;
    }

    &[data-truncate] {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    &[data-line-clamp] {
      display: -webkit-box;
      overflow: hidden;
      white-space: normal;
      -webkit-box-orient: vertical;
    }
  }
}
